package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonObjectFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.ser.BeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.UnwrappingBeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.std.StringSerializer;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class BeanPropertyWriter_serializeAsField_TriageGen0Test {

    private BeanPropertyWriter writer;
    private JsonGenerator jgen;
    private SerializerProvider prov;
    private PropertySerializerMap map;
    private JsonSerializer<Object> serializer;
    private JsonSerializer<Object> nullSerializer;
    private JavaType type;

    // Marker for empty suppression
    private static final Object MARKER_FOR_EMPTY = new Object();

    @Before
    public void setUp() throws Exception {
        jgen = mock(JsonGenerator.class);
        prov = mock(SerializerProvider.class);
        map = mock(PropertySerializerMap.class);
        serializer = mock(JsonSerializer.class);
        nullSerializer = mock(JsonSerializer.class);
        type = mock(JavaType.class);

        // Since BeanPropertyWriter is protected/internal, we use a subclass or reflection to mock/instantiate
        // For this test, we will use a Mockito spy or a mock of the class if possible, 
        // but since we need to test the real logic, we use a concrete implementation or reflection.
        // We'll simulate a subclass to access protected fields via reflection if necessary.
        writer = spy(new TestBeanPropertyWriter("testField"));

        // Inject dependencies into the writer using reflection because they are protected/private
        setField(writer, "_dynamicSerializers", map);
        setField(writer, "_serializer", null); // Start with null to test dynamic lookup
        setField(writer, "_nullSerializer", null);
        setField(writer, "_name", com.fasterxml.jackson.core.io.SerializedString.valueOf("testField"));
    }

    private void setField(Object target, String name, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    /**
     * Concrete subclass to allow instantiation and testing
     */
    private static class TestBeanPropertyWriter extends BeanPropertyWriter {
        private final String fieldName;

        protected TestBeanPropertyWriter(String fieldName) {
            super(null); // base is null
            this.fieldName = fieldName;
        }

        @Override
        public Object get(Object bean) throws Exception {
            // Simulate getting a value from a bean via reflection for testing
            if (bean instanceof TestBean) {
                return ((TestBean) bean).value;
            }
            return null;
        }

        @Override
        protected void _handleSelfReference(Object bean, JsonSerializer<?> ser) {
            // No-op for testing
        }
    }

    public static class TestBean {
        public Object value;
        public TestBean(Object value) { this.value = value; }
    }

    @Test
    public void testSerialize_NullWithNoNullSerializer() throws Exception {
        TestBean bean = new TestBean(null);
        writer.serializeAsField(bean, jgen, prov);
        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerialize_NullWithNullSerializer() throws Exception {
        TestBean bean = new TestBean(null);
        setField(writer, "_nullSerializer", nullSerializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(nullSerializer).serialize(eq(null), eq(jgen), eq(prov));
    }

    @Test
    public void testSerialize_NormalValue_WithDynamicSerializer() throws Exception {
        String val = "hello";
        TestBean bean = new TestBean(val);
        when(map.serializerFor(val.getClass())).thenReturn(serializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(eq(val), eq(jgen), eq(prov));
    }

    @Test
    public void testSerialize_NormalValue_WithPreAssignedSerializer() throws Exception {
        String val = "hello";
        TestBean bean = new TestBean(val);
        setField(writer, "_serializer", serializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(eq(val), eq(jgen), eq(prov));
    }

    @Test
    public void testSerialize_SuppressEmptyValue() throws Exception {
        Object emptyVal = new Object() {
            @Override
            public String toString() { return ""; }
        };
        // We need a real serializer or a mock that returns true for isEmpty
        TestBean bean = new TestBean(emptyVal);
        setField(writer, "_serializer", serializer);
        setField(writer, "_suppressableValue", MARKER_FOR_EMPTY);
        when(serializer.isEmpty(emptyVal)).thenReturn(true);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerialize_SuppressSpecificValue() throws Exception {
        Integer val = 42;
        TestBean bean = new TestBean(val);
        setField(writer, "_serializer", serializer);
        setField(writer, "_suppressableValue", 42);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen, never()).writeFieldName(any());
    }

    @Test
    public void testSerialize_SelfReference() throws Exception {
        TestBean bean = new TestBean(null);
        bean.value = bean; // Self reference
        setField(writer, "_serializer", serializer);

        writer.serializeAsField(bean, jgen, prov);

        verify(writer)._handleSelfReference(eq(bean), eq(serializer));
        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(eq(bean), eq(jgen), eq(prov));
    }

    @Test
    public void testSerialize_WithTypeSerializer() throws Exception {
        String val = "hello";
        TestBean bean = new TestBean(val);
        setField(writer, "_serializer", serializer);
        setField(writer, "_typeSerializer", type);

        writer.serializeAsField(bean, jgen, prov);

        verify(jgen).writeFieldName(any());
        verify(serializer).serializeWithType(eq(val), eq(jgen), eq(prov), eq(type));
        verify(serializer, never()).serialize(any(), any(), any());
    }

    @Test
    public void testSerialize_FindAndAddDynamic() throws Exception {
        String val = "hello";
        TestBean bean = new TestBean(val);
        // Mock the internal method _findAndAddDynamic
        doReturn(serializer).when(writer)._findAndAddDynamic(eq(map), eq(val.getClass()), eq(prov));
        when(map.serializerFor(val.getClass())).thenReturn(null);

        writer.serializeAsField(bean, jgen, prov);

        verify(writer)._findAndAddDynamic(eq(map), eq(val.getClass()), eq(prov));
        verify(jgen).writeFieldName(any());
        verify(serializer).serialize(eq(val), eq(jgen), eq(prov));
    }
}
